function applyDrillCopy(moduleId: Wave4ModuleId, drillId: string, source: DrillCopy) {
  const target = moduleById[moduleId].drills.find((drill) => drill.id === drillId);
  if (!target) throw new Error(`Missing drill ${drillId}`);
  if (target.actionOptions.length !== 3 || target.reasonOptions.length !== 3) throw new Error(`Unexpected option count for ${drillId}`);
  target.assumptions = [...source.assumptions];
  target.cue = source.cue;
  target.question = source.question;
  target.actionOptions.forEach((option, index) => { option.text = source.actions[index]; });
  target.reasonOptions.forEach((option, index) => { option.text = source.reasons[index]; });
  target.explanation = source.explanation;
}

function applyModuleCopy(moduleId: Wave4ModuleId, source: ModuleCopy) {
  const target = moduleById[moduleId];
  Object.assign(target, {
    title: source.title,
    shortTitle: source.shortTitle,
    description: source.description,
    scope: source.scope,
    plainGoal: source.plainGoal,
    tableCue: source.tableCue,
    technicalTerm: source.technicalTerm,
    theory: [...source.theory],
    heuristics: [...source.heuristics],
    decisionTree: [...source.decisionTree],
    workedExample: { ...source.workedExample, steps: [...source.workedExample.steps] },
    counterexample: source.counterexample,
    lab: { type: "compare" as const, ...source.lab },
    explainBackPrompt: source.explainBackPrompt,
    tableCard: [...source.tableCard],
    glossary: source.glossary.map((item) => ({ ...item })),
  });
  for (const [drillId, drill] of Object.entries(source.drills)) applyDrillCopy(moduleId, drillId, drill);
  for (const [cardId, [front, back]] of Object.entries(source.cards)) {
    const card = target.flashcards.find((item) => item.id === cardId);
    if (!card) throw new Error(`Missing card ${cardId}`);
    card.front = front;
    card.back = back;
  }
}

export const wave4CurriculumModuleIds = ["filtering", "shape", "ancestry", "multiway", "river", "evidence", "transfer"] as const satisfies readonly ModuleId[];

export function applyWave4CurriculumLocale(locale: LocaleCode) {
  const source = locale === "ru" ? RU_WAVE4 : EN_WAVE4;
  for (const moduleId of wave4CurriculumModuleIds) applyModuleCopy(moduleId, source[moduleId]);
}
